#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;
vector<long long> factorialsArray;

long long quickPow(long long base, long long exp) {
    long long res = 1LL;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

long long choose(int n, int r) {
    if (r == 0 || r == n) return 1LL;
    if (r > n || r < 0) return 0LL;
    long long numerator = factorialsArray[n];
    long long denominator = (factorialsArray[r] * factorialsArray[n - r]) % MOD;
    return (numerator * quickPow(denominator, MOD - 2)) % MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int totalN;
    long long totalK;
    cin >> totalN >> totalK;
    factorialsArray.resize(totalN + 1);
    factorialsArray[0] = 1LL;
    for (int i = 1; i <= totalN; i++) {
        factorialsArray[i] = (factorialsArray[i - 1] * i) % MOD;
    }
    if (totalK == 0) {
        cout << factorialsArray[totalN] << "\n";
    } else if (totalK >= totalN) {
        cout << 0 << "\n";
    } else {
        int kInt = (int) totalK;
        long long sumTerms = 0LL;
        long long signFlag = 1LL;
        int lVal = totalN - kInt;
        for (int i = 0; i <= lVal; i++) {
            long long term = (quickPow(lVal - i, totalN) * choose(lVal, lVal - i)) % MOD;
            sumTerms = (sumTerms + signFlag * term + MOD) % MOD;
            signFlag *= -1LL;
        }
        long long answer = (2LL * choose(totalN, kInt) * sumTerms) % MOD;
        cout << answer << "\n";
    }
    return 0;
}
